CITIES.slice(1).forEach((c,i)=>districtNames[i].forEach((name,j)=>{const segment=['specialty','tourist',j===2?'office':'community'][j],sg=SEGMENTS[segment];LOCATIONS.push({id:i===0&&j===0?'brno':i===0&&j===1?'brnostred':i===1&&j===0?'viden':i===1&&j===1?'videnstred':'c'+(i+1)+'-'+j,name,city:c.name,x:[28,58,75][j],y:[34,62,27][j],rent:round([12000,19000,14500][j]*c.mult),setup:round([290000,420000,340000][j]*c.mult),traffic:round(sg.traffic*(1+i*.025)),segment,ideal:round(sg.price*c.mult)});}));
const ORIGINS={brazil:{name:'Brazílie · Cerrado',cost:210,quality:74,taste:'Čokoláda, oříšky',roast:3},colombia:{name:'Kolumbie · Huila',cost:285,quality:84,taste:'Karamel, citrusy',roast:2},ethiopia:{name:'Etiopie · Sidamo',cost:360,quality:94,taste:'Jasmín, bergamot',roast:1},kenya:{name:'Keňa · Nyeri',cost:390,quality:96,taste:'Rybíz, červené ovoce',roast:1},robusta:{name:'Vietnam · Dak Lak',cost:155,quality:52,taste:'Kakao, koření',roast:3}};
const MANAGERS=[{name:'Anna Nováková',skill:90,salary:9000,trait:'Kvalita a tým',initials:'AN'},{name:'David Veselý',skill:78,salary:6800,trait:'Efektivní provoz',initials:'DV'},{name:'Eliška Malá',skill:85,salary:7900,trait:'Hosté a značka',initials:'EM'},{name:'Tomáš Kučera',skill:93,salary:10500,trait:'Výroba a logistika',initials:'TK'}];
const CONCEPTS={community:{name:'Sousedská kavárna',cost:80000,quality:2},express:{name:'Espresso & go',cost:65000,quality:0},specialty:{name:'Výběrová kavárna',cost:120000,quality:5}};
const OFFICE_OPTIONS=[{id:'studio',name:'Zakladatelské studio',cost:380000,seats:16,upkeep:3500},{id:'hq',name:'Centrála v Karlíně',cost:850000,seats:40,upkeep:6500},{id:'campus',name:'Mezinárodní sídlo',cost:2100000,seats:100,upkeep:12500}];
const DEPARTMENTS={hr:{name:'HR',salary:7500,description:'Zkracuje nábor, školí lidi a zlepšuje motivaci. Jeden člověk pokryje čtyři kavárny.'},finance:{name:'Finance',salary:9000,description:'Plánuje rezervu na šest týdnů, hlídá náklady a snižuje úrok úvěru.'},sales:{name:'Obchod',salary:8500,description:'Každý obchodník umožní jeden velkoobchodní kontrakt a pomáhá s cenou.'},product:{name:'Produkt',salary:9000,description:'Zlepšuje receptury a řídí ochutnávky i sezónní nabídku.'},it:{name:'IT',salary:9500,description:'Buduje věrnostní aplikaci a e-shop. Provoz a vývoj potřebují lidi i rozpočet.'}};
const ESTATES=[{id:'cerrado',name:'Fazenda Aurora',country:'Brazílie',origin:'brazil',cost:540000,hectares:12,yield:520,quality:76,upkeep:6000,period:12},{id:'huila',name:'Finca Esperanza',country:'Kolumbie',origin:'colombia',cost:760000,hectares:10,yield:420,quality:87,upkeep:7200,period:12},{id:'sidamo',name:'Sidamo Highlands',country:'Etiopie',origin:'ethiopia',cost:980000,hectares:9,yield:330,quality:95,upkeep:8000,period:14},{id:'nyeri',name:'Nyeri Cooperative',country:'Keňa',origin:'kenya',cost:1150000,hectares:8,yield:300,quality:97,upkeep:8500,period:14}];
const ROASTER_OPTIONS=[{id:'artisan',name:'Řemeslná pražírna',cost:320000,capacity:140,upkeep:4000},{id:'industrial',name:'Produkční pražírna',cost:890000,capacity:420,upkeep:7500},{id:'hub',name:'Exportní pražírna',cost:1650000,capacity:850,upkeep:12000}];
function loc(id){return LOCATIONS.find(l=>l.id===id)}
function uid(prefix){return prefix+'-'+state.nextId++}
function makeStore(id,brand='brand-1',blend='blend-1'){const l=loc(id);return {id,brand,blend,price:l.ideal,staff:Math.ceil(l.traffic/400),wage:6500,marketing:1500,quality:67,loyalty:18,manager:null,policy:'quality',budget:4500,auto:{staff:true,price:true,marketing:true},franchise:false,last:null};}
function fresh(){return {version:2,nextId:20,week:1,cash:1600000,reputation:48,stores:[makeStore('karlin')],brands:[{id:'brand-1',name:'Kavárna',concept:'community',color:'#264b3b',budget:0,reputation:48}],blends:[{id:'blend-1',name:'První světlo',primary:'brazil',secondary:'colombia',share:75,roast:3,packaging:'classic',price:490,research:0}],green:[{origin:'brazil',kg:140,cost:210,quality:74},{origin:'colombia',kg:60,cost:285,quality:84}],batches:[{blend:'blend-1',kg:55,quality:75,cost:338,roastedWeek:1}],shipments:[],roasters:[{id:'roaster-1',name:'Karlín · první pražírna',type:'artisan',capacity:120,upkeep:3500,condition:95,staff:2,wage:5500,shifts:1,manager:null,auto:true,priority:'quality',last:null}],estates:[],offices:[],departments:{hr:0,finance:0,sales:0,product:0,it:0},projects:{loyalty:{progress:0,done:false,budget:0},eshop:{progress:0,done:false,budget:0}},contracts:[],regions:[],rivals:[{id:'daily',name:'Daily Cup',strategy:'volume',cash:1500000,reputation:48,priceFactor:.9,stores:['centrum','brnostred'],debt:0,lastProfit:0,history:[],bankrupt:false},{id:'atelier',name:'Atelier Coffee',strategy:'quality',cash:1900000,reputation:67,priceFactor:1.12,stores:['c3-0'],debt:0,lastProfit:0,history:[],bankrupt:false},{id:'north',name:'North Bean',strategy:'community',cash:1250000,reputation:56,priceFactor:1,stores:['c4-2'],debt:0,lastProfit:0,history:[],bankrupt:false}],history:[],logs:[{week:1,text:'Tvoje první kavárna a pražírna mají otevřeno.',detail:'Začínáš v Karlíně, s vlastní směsí a hotovostí 1,6 milionu Kč.'}],trust:65,debt:0,loanTaken:false,founderShare:100,dividends:0,expansionBudget:0,boardCooldown:0,win:false,over:false,event:null,totalCups:0};}
let state=fresh();
function log(text,detail=''){state.logs.unshift({week:state.week,text,detail});state.logs=state.logs.slice(0,100)}
function spend(n){if(!Number.isFinite(n)||n<0)throw Error('Neplatná částka.');if(state.cash<n)throw Error('Na tento krok nemáš dost hotovosti.');state.cash-=n}
function guard(){if(state.over)throw Error(state.sold?'Firma byla prodána. Začni novou kampaň nebo načti uložený postup.':'Hra skončila platební neschopností. Načti uloženou hru nebo začni znovu.')}
function blend(id){return state.blends.find(b=>b.id===id)}
function brand(id){return state.brands.find(b=>b.id===id)}
function recipe(b){const a=ORIGINS[b.primary],z=ORIGINS[b.secondary],w=b.share/100;return {quality:clamp(a.quality*w+z.quality*(1-w)-Math.abs(b.roast-a.roast)*5*w-Math.abs(b.roast-z.roast)*5*(1-w)+Math.min(6,b.research||0),30,99),cost:a.cost*w+z.cost*(1-w),taste:a.taste+' / '+z.taste};}
function coffeeQuality(id='blend-1'){const b=blend(id)||state.blends[0];return round(recipe(b).quality)}
function greenAmount(origin){return state.green.filter(g=>g.origin===origin).reduce((a,g)=>a+g.kg,0)}
function stock(id){return state.batches.filter(b=>b.blend===id).reduce((a,b)=>a+b.kg,0)}
function stockQuality(id){const lots=state.batches.filter(b=>b.blend===id),kg=stock(id);return kg?round(lots.reduce((a,b)=>a+b.kg*batchQuality(b),0)/kg):coffeeQuality(id)}
function batchQuality(b){return clamp(b.quality-Math.max(0,state.week-b.roastedWeek-1)*5,25,99)}
function takeGreen(origin,kg){let left=kg,cost=0,quality=0;for(const g of state.green){if(g.origin!==origin||left<=0)continue;const n=Math.min(g.kg,left);g.kg-=n;left-=n;cost+=n*g.cost;quality+=n*g.quality;}state.green=state.green.filter(g=>g.kg>.001);if(left>.001)throw Error('Chybí zrna pro recepturu.');return {cost,quality:kg?quality/kg:0};}
function takeCoffee(id,kg){let left=kg,cost=0,quality=0,used=0;state.batches.sort((a,b)=>a.roastedWeek-b.roastedWeek);for(const b of state.batches){if(b.blend!==id||left<=0)continue;const n=Math.min(b.kg,left);b.kg-=n;left-=n;cost+=n*b.cost;quality+=n*batchQuality(b);used+=n;}state.batches=state.batches.filter(b=>b.kg>.001);return {kg:used,cost,quality:used?quality/used:coffeeQuality(id)};}
function owned(id){return state.stores.some(s=>s.id===id)}
function occupant(id){return state.rivals.find(r=>!r.bankrupt&&r.stores.includes(id))}
function unlocked(name){const c=CITIES.find(c=>c.name===name);return !!c&&state.stores.length>=c.unlock&&state.reputation>=c.reputation}
function openStore(id,brandId='brand-1',blendId='blend-1',franchise=false){guard();const l=loc(id);if(!l||!brand(brandId)||!blend(blendId))throw Error('Neplatná lokalita, značka nebo směs.');if(owned(id))throw Error('Tuhle pobočku už vlastníš.');if(occupant(id))throw Error('Lokalitu obsadila konkurence. Můžeš převzít celou její firmu.');if(!unlocked(l.city))throw Error('Město zatím není odemčené. Podmínky vidíš na mapě.');if(franchise&&state.reputation<65)throw Error('Franšízy vyžadují pověst 65.');const cost=franchise?round(l.setup*.25):(typeof openingSetupCost5==='function'?openingSetupCost5(l):l.setup);if(state.stores.length>=4&&state.founderShare<50&&state.expansionBudget<cost)throw Error('Při menšinovém podílu potřebuješ expanzní mandát boardu.');spend(cost);if(state.founderShare<50&&state.stores.length>=4)state.expansionBudget-=cost;const s=makeStore(id,brandId,blendId);s.franchise=franchise;if(franchise)s.manager={...MANAGERS[1]};state.stores.push(s);log((franchise?'Nová franšíza: ':'Nová kavárna: ')+l.city+' · '+l.name,'Investice '+money(cost)+'. Příští týden začne běžný provoz.');}
function hire(id,index,kind='store'){guard();const collection=kind==='roaster'?state.roasters:kind==='estate'?state.estates:state.stores;const entity=collection.find(s=>s.id===id),m=MANAGERS[index];if(!entity||!m)throw Error('Neplatný výběr.');spend(Math.max(4000,12000-state.departments.hr*1500));entity.manager={...m};log(m.name+' přebírá '+(entity.name||loc(id).name),'Týdenní mzda '+money(m.salary)+'.')}
function fire(id,kind='store'){guard();const e=(kind==='roaster'?state.roasters:kind==='estate'?state.estates:state.stores).find(e=>e.id===id);if(!e?.manager)throw Error('Tato pozice není obsazená.');log(e.manager.name+' opouští vedení.');e.manager=null;}
function createBrand(name,concept,color){guard();name=String(name).trim();if(!name||name.length>40||!CONCEPTS[concept]||!/^#[a-f0-9]{6}$/i.test(color))throw Error('Zkontroluj název, koncept a barvu.');if(state.brands.length>=8)throw Error('Ve firmě můžeš mít až osm značek.');spend(CONCEPTS[concept].cost);const b={id:uid('brand'),name,concept,color,budget:0,reputation:state.reputation};state.brands.push(b);log('Vznikla značka '+name,CONCEPTS[concept].name);return b;}
function updateBrand(id,data){guard();const b=brand(id);if(!b)throw Error('Neznámá značka.');if(!data.name?.trim()||data.name.length>40||!CONCEPTS[data.concept]||!/^#[a-f0-9]{6}$/i.test(data.color)||!Number.isInteger(data.budget)||data.budget<0||data.budget>20000)throw Error('Neplatné nastavení značky.');if(b.concept!==data.concept)spend(CONCEPTS[data.concept].cost*.5);Object.assign(b,{...data,name:data.name.trim()});}
function createBlend(data){guard();if(state.blends.length>=10)throw Error('Můžeš mít až deset receptur.');validateRecipe(data);spend(15000);const b={id:uid('blend'),...data,research:0};state.blends.push(b);log('Nová káva: '+b.name,'Receptura je připravená. Přiděl ji kavárně nebo obchodnímu kontraktu.');return b;}
function validateRecipe(b){if(!b.name?.trim()||b.name.length>40||!ORIGINS[b.primary]||!ORIGINS[b.secondary]||!Number.isInteger(b.share)||b.share<50||b.share>100||![1,2,3].includes(b.roast)||!['classic','premium','eco'].includes(b.packaging)||!Number.isInteger(b.price)||b.price<250||b.price>1200)throw Error('Zkontroluj název, původ, poměr, pražení, obal a cenu.');}
function updateBlend(id,data){guard();validateRecipe(data);const b=blend(id);if(!b)throw Error('Neznámá směs.');Object.assign(b,data);log('Receptura upravena: '+b.name,'Nové nastavení platí až pro nově upražené šarže. Staré zásoby si zachovávají původní chuť a náklad.');}
function orderBeans(origin,kg){guard();if(!ORIGINS[origin]||!Number.isInteger(kg)||kg<1||kg>2500)throw Error('Objednávka musí mít 1–2 500 kg a platný původ.');const o=ORIGINS[origin],cost=kg*o.cost;spend(cost);state.shipments.push({id:uid('shipment'),origin,kg,cost:o.cost,quality:o.quality,due:state.week+1,source:'Dodavatel'});log('Objednáno '+kg+' kg: '+o.name,'Dodání v týdnu '+(state.week+1)+', zaplaceno '+money(cost)+'.');}
function roasterCapacity(r){return round(r.capacity*r.shifts*clamp(r.condition/100,.35,1)*Math.min(1,r.staff/(2*r.shifts)));}
function roastBatch(r,b,kg,emergency=false){const a=kg*b.share/100,z=kg-a;const has=greenAmount(b.primary)+1e-8>=a&&(b.primary===b.secondary?greenAmount(b.primary)+1e-8>=kg:greenAmount(b.secondary)+1e-8>=z);if(!has)throw Error('Pro tuto šarži chybí zrna.');const processing=kg*(typeof roastProcessingCost5==='function'?roastProcessingCost5(r,b):55);spend(processing);const x=takeGreen(b.primary,a),y=takeGreen(b.secondary,z),quality=(x.quality*a+y.quality*z)/kg-Math.abs(b.roast-ORIGINS[b.primary].roast)*5*a/kg-Math.abs(b.roast-ORIGINS[b.secondary].roast)*5*z/kg+Math.min(6,b.research)+((r.manager?.skill||65)-65)*.07-(r.condition<65?6:0);const kgOut=kg*(typeof roastYield5==='function'?roastYield5(r,b):.84);state.batches.push({blend:b.id,kg:kgOut,quality:clamp(quality,25,99),cost:(x.cost+y.cost+processing)/kgOut,roastedWeek:state.week});r.condition=clamp(r.condition-kg/r.capacity*1.2,20,100);return {kg:kgOut,processing,emergency};}
function manualRoast(id,blendId,kg){guard();const r=state.roasters.find(r=>r.id===id),b=blend(blendId);if(!r||!b||!Number.isInteger(kg)||kg<1||kg*(typeof roastEffort5==='function'?roastEffort5(r,b):1)>roasterCapacity(r)-(r.manualUsed||0))throw Error('Šarže přesahuje volnou kapacitu pražírny pro tento týden.');const result=roastBatch(r,b,kg);r.manualUsed=(r.manualUsed||0)+kg*(typeof roastEffort5==='function'?roastEffort5(r,b):1);if(typeof recordCraftManual5==='function')recordCraftManual5(r,b,kg,result.kg);log('Upraženo '+round(result.kg)+' kg: '+b.name,r.name+' · zelená káva '+kg+' kg.');}
function buyRoaster(type,name){guard();const o=ROASTER_OPTIONS.find(o=>o.id===type);if(!o||state.roasters.length>=8||!name?.trim()||name.length>40)throw Error('Neplatná pražírna. Maximum je osm provozů.');spend(o.cost);const r={id:uid('roaster'),name:name.trim(),type,capacity:o.capacity,upkeep:o.upkeep,condition:100,staff:2,wage:5500,shifts:1,manager:null,auto:true,priority:'quality',last:null};state.roasters.push(r);log('Koupena pražírna '+name,'Investice '+money(o.cost)+', kapacita '+o.capacity+' kg zelené kávy za směnu týdně.');return r;}
function maintainRoaster(id){guard();const r=state.roasters.find(r=>r.id===id);if(!r)throw Error('Neznámá pražírna.');spend(18000);r.condition=100;log('Servis pražírny '+r.name,'Technický stav obnoven na 100 %.');}
function upgradeRoaster(id){guard();const r=state.roasters.find(r=>r.id===id);if(!r||r.capacity>=1000)throw Error('Tuto pražírnu nelze dál rozšířit.');spend(round(r.capacity*1800));r.capacity=round(r.capacity*1.5);r.condition=100;r.upkeep=round(r.upkeep*1.15);log('Rozšířena pražírna '+r.name,'Nová kapacita '+r.capacity+' kg za směnu.');}
function buyEstate(id){guard();const o=ESTATES.find(e=>e.id===id);if(!o||state.estates.some(e=>e.sourceId===id))throw Error('Plantáž už vlastníš nebo neexistuje.');spend(o.cost);const e={...o,id:uid('estate'),sourceId:id,manager:null,staff:4,wage:2600,method:'balanced',irrigation:false,health:85,cycle:0,yieldUpgrade:0,wipCost:0,last:null};state.estates.push(e);log('Koupena plantáž '+o.name,o.country+' · první sklizeň za '+o.period+' týdnů.');return e;}
function irrigation(id){guard();const e=state.estates.find(e=>e.id===id);if(!e||e.irrigation)throw Error('Plantáž už má závlahu nebo neexistuje.');spend(90000);e.irrigation=true;log('Závlaha na '+e.name,'Dopad sucha je nižší a zdravotní stav porostu stabilnější.');}
function expandEstate(id){guard();const e=state.estates.find(e=>e.id===id);if(!e)throw Error('Neznámá plantáž.');spend(round(e.cost*.25));e.yieldUpgrade++;e.hectares+=3;e.upkeep=round(e.upkeep*1.15);log('Rozšířena plantáž '+e.name,'Výnos sklizně +25 % původní kapacity. Větší plocha potřebuje více pracovníků.');}
function buyOffice(id){guard();const o=OFFICE_OPTIONS.find(o=>o.id===id);if(!o||state.offices.length>=4)throw Error('Neplatná kancelář nebo dosažen limit čtyř budov.');spend(o.cost);state.offices.push({...o,id:uid('office')});log('Koupeno sídlo: '+o.name,'Kapacita '+o.seats+' pracovních míst pro oddělení a regionální vedení.');}
function officeSeats(){return state.offices.reduce((a,o)=>a+o.seats,0)}
function usedSeats(){return Object.values(state.departments).reduce((a,n)=>a+n,0)+state.regions.length+1;}
function setDepartment(key,n){guard();if(!DEPARTMENTS[key]||!Number.isInteger(n)||n<0||n>30)throw Error('Oddělení může mít 0–30 zaměstnanců.');const old=state.departments[key];if(n>old&&!officeSeats())throw Error('Nejdřív pořiď kanceláře.');if(usedSeats()-old+n>officeSeats()&&n>old)throw Error('V kancelářích není dost pracovních míst.');if(n>old)spend((n-old)*8000);state.departments[key]=n;log(DEPARTMENTS[key].name+': '+n+' zaměstnanců',n>old?'Nábor '+money((n-old)*8000)+'.':'Velikost týmu upravena.');}
function startProject(key,budget){guard();if(!state.projects[key]||!Number.isInteger(budget)||budget<0||budget>20000)throw Error('Neplatný projekt nebo rozpočet.');if(budget>0&&!state.departments.it)throw Error('Projekt potřebuje alespoň jednoho člověka v IT.');state.projects[key].budget=budget;}
function addRegion(city,index){guard();if(!CITIES.some(c=>c.name===city)||state.regions.some(r=>r.city===city)||!MANAGERS[index])throw Error('Neplatný region nebo regionální vedení už existuje.');if(!officeSeats()||usedSeats()+1>officeSeats())throw Error('Pro oblastního ředitele potřebuješ volné místo v kanceláři.');spend(20000);state.regions.push({city,manager:{...MANAGERS[index]},auto:true,last:[]});log('Oblastní vedení: '+city,MANAGERS[index].name+' přebírá region.');}
function assignRegion(city,policy,budget){guard();if(!['quality','growth','profit'].includes(policy)||!Number.isInteger(budget)||budget<0||budget>10000)throw Error('Neplatná regionální politika.');const reg=state.regions.find(r=>r.city===city);if(!reg)throw Error('Nejdřív najmi oblastního ředitele.');state.stores.filter(s=>loc(s.id).city===city&&!s.franchise).forEach(s=>{s.policy=policy;s.budget=budget;s.auto={staff:true,price:true,marketing:true}});log('Nová pravidla pro '+city,'Cíl '+policy+', maximální marketing '+money(budget)+' / pobočka.');}
function signContract(blendId,kg){guard();const b=blend(blendId);if(!b||!Number.isInteger(kg)||kg<5||kg>100)throw Error('Kontrakt musí mít 5–100 kg týdně.');if(state.contracts.length>=state.departments.sales)throw Error('Každý kontrakt potřebuje jednoho obchodníka.');const c={id:uid('contract'),name:['Hotel Central','Bistro & Co','Office Hub','Market Pantry'][state.contracts.length%4],blend:blendId,kg,price:round(b.price*(.82+Math.min(.08,state.departments.sales*.015))),remaining:12,fulfilled:0,last:null};state.contracts.push(c);log('Nový kontrakt: '+c.name,kg+' kg týdně na 12 týdnů. Nedodání stojí 15 % hodnoty chybějící kávy.');return c;}
function researchBlend(id){guard();const b=blend(id);if(!b||!state.departments.product)throw Error('Vývoj receptury potřebuje oddělení Produkt.');if(b.research>=6)throw Error('Receptura už je plně optimalizovaná.');spend(20000);b.research=Math.min(6,b.research+state.departments.product*2);log('Ochutnávka dokončena: '+b.name,'Nově pražená káva získá až '+Math.min(6,b.research)+' bodů kvality navíc.');}
function acquireRival(id){guard();const r=state.rivals.find(r=>r.id===id);if(!r||r.bankrupt||!r.stores.length)throw Error('Firma není dostupná k převzetí.');const price=rivalValuation(r);if(state.founderShare<50&&state.expansionBudget<price)throw Error('Akvizice potřebuje expanzní mandát.');spend(price);if(state.founderShare<50)state.expansionBudget-=price;const acquiredCash=Math.max(0,r.cash);state.cash+=acquiredCash;state.debt+=r.debt;for(const id of r.stores){const s=makeStore(id);s.price=round(loc(id).ideal*r.priceFactor);s.manager={...MANAGERS[1]};state.stores.push(s)}log('Převzata společnost '+r.name,r.stores.length+' poboček, cena '+money(price)+', převzatá hotovost '+money(acquiredCash)+' a dluh '+money(r.debt)+'.');r.stores=[];r.cash=0;r.debt=0;r.bankrupt=true;r.acquired=true;}
function rivalValuation(r){return round(Math.max(0,r.cash)+r.stores.reduce((a,id)=>a+loc(id).setup*.85,0)+Math.max(0,r.lastProfit)*12-r.debt*.4)}
function proposal(type){const avg=state.history.slice(-4).reduce((a,h)=>a+h.profit,0)/Math.max(1,state.history.slice(-4).length),managed=state.stores.filter(s=>s.manager||s.franchise).length,capacity=state.roasters.reduce((a,r)=>a+roasterCapacity(r)*.84,0),need=state.stores.reduce((a,s)=>a+loc(s.id).traffic*.018,0),q=state.blends.reduce((a,b)=>a+coffeeQuality(b.id),0)/state.blends.length;let votes;
if(type==='expansion')votes=[{name:'Petr · finance',yes:state.cash>=550000&&avg>0,reason:state.cash<550000?'Rezerva musí být alespoň 550 000 Kč.':avg<=0?'Poslední čtyři týdny musí být v průměru ziskové.':'Zisk a hotovost dovolují růst.'},{name:'Jana · provoz',yes:managed>=Math.ceil(state.stores.length*.6)&&capacity>=need*1.1,reason:managed<Math.ceil(state.stores.length*.6)?'Manažera musí mít alespoň 60 % poboček.':capacity<need*1.1?'Pražírny potřebují kapacitu alespoň 110 % základní potřeby.':'Vedení i výroba mají kapacitu pro růst.'},{name:'Lucie · produkt',yes:q>=75&&state.reputation>=55,reason:q<75?'Průměrná kvalita receptur musí být alespoň 75.':state.reputation<55?'Pověst musí být alespoň 55.':'Kvalita a značka jsou připravené.'}];
if(type==='roastery')votes=[{name:'Petr · finance',yes:state.cash>=450000,reason:state.cash>=450000?'Investice má dostatečné krytí.':'Potřebujeme rezervu 450 000 Kč.'},{name:'Jana · provoz',yes:state.stores.length>=2,reason:state.stores.length>=2?'Více kaváren využije větší výrobu.':'Nejdřív provozuj alespoň dvě kavárny.'},{name:'Lucie · produkt',yes:q>=70,reason:q>=70?'Vlastní káva dává investici smysl.':'Průměrná kvalita receptur musí být 70.'}];
if(type==='dividend')votes=[{name:'Petr · finance',yes:state.cash>=1000000&&avg>30000,reason:state.cash<1000000?'Rezerva musí být alespoň milion.':avg<=30000?'Průměrný zisk musí být nad 30 000 Kč.':'Zisk i rezerva jsou dostatečné.'},{name:'Jana · provoz',yes:state.stores.every(s=>s.quality>=65),reason:state.stores.every(s=>s.quality>=65)?'Provozy mají přijatelnou kvalitu.':'Některé kavárny mají kvalitu pod 65.'},{name:'Lucie · produkt',yes:state.reputation>=65,reason:state.reputation>=65?'Silná značka dovoluje výplatu.':'Pověst musí být alespoň 65.'}];
if(!votes)throw Error('Neplatný návrh.');return {votes,passed:votes.filter(v=>v.yes).length>=2,avg,control:state.founderShare>=50};}
function board(type,override=false){guard();if(state.week<state.boardCooldown)throw Error('Další zasedání v týdnu '+state.boardCooldown+'.');const p=proposal(type);if(override&&!p.control)throw Error('Nemáš většinový podíl.');if((p.passed||override)&&type==='roastery'&&state.cash<180000)throw Error('Na investici nemáš hotovost.');if((p.passed||override)&&type==='dividend'&&state.cash<100000)throw Error('Na dividendu nemáš hotovost.');state.boardCooldown=state.week+3;if(p.passed||override){if(type==='expansion'){state.expansionBudget=3000000;log('Schválen expanzní mandát','Investice až do 3 milionů Kč ze stávající hotovosti.')}if(type==='roastery'){const r=state.roasters[0];spend(180000);r.capacity+=100;r.condition=100;log('Schváleno rozšíření první pražírny','Kapacita +100 kg za směnu.')}if(type==='dividend'){spend(100000);state.dividends+=100000*state.founderShare/100;log('Vyplacena dividenda '+money(100000),'Zakladatel obdržel '+money(100000*state.founderShare/100)+' podle svého podílu.')}if(override&&!p.passed){state.trust=clamp(state.trust-10,10,99);log('Zakladatel prosadil rozhodnutí většinovým podílem','Board měl výhrady; důvěra klesla o 10 bodů.')}}else log('Board zamítl návrh',p.votes.filter(v=>!v.yes).map(v=>v.reason).join(' '));return {...p,approved:p.passed||override};}
function takeLoan(){guard();const limit=400000+state.stores.length*100000;if(state.debt>=limit)throw Error('Úvěrový limit je vyčerpaný.');const amount=Math.min(400000,limit-state.debt);state.cash+=amount;state.debt+=amount;log('Čerpán úvěr '+money(amount),'Limit závisí na velikosti sítě. Úrok 0,2 % týdně před efektem Finančního oddělení.');}
function repay(){guard();if(!state.debt)throw Error('Nemáš dluh.');const n=Math.min(state.debt,100000);spend(n);state.debt-=n;log('Splaceno '+money(n)+' z úvěru.');}
function raiseCapital(){guard();if(state.founderShare<=25)throw Error('Další podíl už nemůžeš nabídnout.');state.founderShare-=25;state.cash+=2000000;log('Investor vložil 2 miliony Kč','Zakladatel nyní vlastní '+state.founderShare+' %. Pod 50 % vyžaduje velká expanze mandát boardu.');}
function forecast(){const h=state.history.at(-1);const burn=h?Math.max(0,-h.cashChange):state.stores.reduce((a,s)=>a+loc(s.id).rent+s.staff*s.wage,0);const reserve=weeklyFixed()*6;return {reserve,runway:burn?state.cash/burn:Infinity,projected:state.cash+(h?.cashChange||0)*6};}
function weeklyFixed(){return state.stores.filter(s=>!s.franchise).reduce((a,s)=>a+loc(s.id).rent+s.staff*s.wage+(s.manager?.salary||0)+3200,0)+state.roasters.reduce((a,r)=>a+r.staff*r.wage+r.upkeep+(r.manager?.salary||0),0)+state.offices.reduce((a,o)=>a+o.upkeep,0)+Object.entries(state.departments).reduce((a,[k,n])=>a+n*DEPARTMENTS[k].salary,0)+state.estates.reduce((a,e)=>a+e.upkeep+e.staff*e.wage+(e.manager?.salary||0),0)+state.regions.reduce((a,r)=>a+r.manager.salary*1.4,0);}
function autoManager(s){const l=loc(s.id),m=s.manager;if(!m)return [];const d=[],buffer=state.cash>Math.max(120000,weeklyFixed()),target=Math.ceil(l.traffic/400);if(s.auto.staff&&buffer){const n=clamp(target+(s.policy==='growth'?1:0),2,7);if(s.staff!==n){d.push('Tým '+s.staff+' → '+n+': kapacita odpovídá poptávce.');s.staff=n}}if(s.auto.price){const concept=brand(s.brand)?.concept||'community',ideal=l.ideal+(s.policy==='profit'?9:s.policy==='growth'?-5:4)+(concept==='specialty'?6:concept==='express'?-5:0),step=clamp(ideal-s.price,-5,5);if(step){s.price+=step;d.push('Cena '+money(s.price)+': cíl '+({quality:'kvalita',growth:'růst',profit:'zisk'})[s.policy]+'.')}}if(s.auto.marketing){const n=buffer?Math.min(s.budget,s.policy==='growth'?5000:s.policy==='profit'?1800:3000):0;if(n!==s.marketing){s.marketing=n;d.push('Marketing '+money(n)+': '+(buffer?'v povoleném rozpočtu.':'pauza kvůli rezervě.'))}}return d;}
function autoRegions(){for(const region of state.regions){region.last=[];if(!region.auto)continue;for(const s of state.stores.filter(s=>loc(s.id).city===region.city&&!s.franchise)){if(!s.manager&&state.cash>weeklyFixed()*4+20000){const m=MANAGERS[1];state.cash-=Math.max(4000,12000-state.departments.hr*1500);s.manager={...m};region.last.push('Obsazen manažer '+loc(s.id).name+'.')}if(s.quality<65&&s.wage<7500&&state.cash>weeklyFixed()*4){s.wage+=500;region.last.push('Mzda v '+loc(s.id).name+' +500 Kč pro stabilnější tým.')}}}}
function processShipments(){for(const s of state.shipments.filter(s=>s.due<=state.week)){state.green.push({origin:s.origin,kg:s.kg,cost:s.cost,quality:s.quality});log('Dodávka '+round(s.kg)+' kg dorazila',ORIGINS[s.origin].name+' · '+s.source)}state.shipments=state.shipments.filter(s=>s.due>state.week);}
function productionNeeds(){const needs={};for(const s of state.stores)needs[s.blend]=(needs[s.blend]||0)+loc(s.id).traffic*.018*1.18;for(const c of state.contracts)needs[c.blend]=(needs[c.blend]||0)+c.kg;if(state.projects.eshop.done&&state.departments.it)for(const b of state.blends)needs[b.id]=(needs[b.id]||0)+Math.max(2,state.reputation*.06);return needs;}
function autoProduction(){let cashSpend=0,inventoryBought=0,processing=0;for(const r of state.roasters){const needs=productionNeeds(state.version>=3?r.zone:undefined);let used=r.manualUsed||0,output=typeof manualRoastOutput5==='function'?manualRoastOutput5(r):used*.84,greenUsed=typeof manualRoastInput5==='function'?manualRoastInput5(r):used,decisions=[],plannedSpend=0;let cap=roasterCapacity(r);if(r.manager&&r.condition<65&&(state.version<3||(state.policy3.autoCrises&&state.policy3.crisisLimit>=18000))&&state.cash>weeklyFixed()*3+18000){state.cash-=18000;r.condition=100;cashSpend+=18000;if(state.version>=3&&state.turnLedger3)state.turnLedger3.crises+=18000;cap=roasterCapacity(r);decisions.push('Preventivní servis: stav obnoven na 100 %.')}if(r.auto){const ordered=state.blends.slice().sort((a,b)=>r.priority==='margin'?recipe(a).cost-recipe(b).cost:(needs[b.id]||0)-(needs[a.id]||0));for(const b of ordered){if(used>=cap)break;const yieldFactor=typeof roastYield5==='function'?roastYield5(r,b):.84,effort=typeof roastEffort5==='function'?roastEffort5(r,b):1;const wanted=Math.min((cap-used)/effort,state.version>=3?Math.max(0,Math.floor((warehouseCapacity(r.zone)-cityStock(r.zone))/yieldFactor)):Infinity,Math.max(0,Math.ceil(((needs[b.id]||0)*(typeof productionBuffer5==='function'?productionBuffer5(r):1.35)-stock(b.id,state.version>=3?r.zone:undefined))/yieldFactor)));const sourceLimit=typeof craftInputLimit5==='function'?craftInputLimit5(b):Infinity,want=Math.min(wanted,sourceLimit);if(want<=.000001){if(wanted>0&&sourceLimit<=.000001)decisions.push('Pražení '+b.name+' pozastaveno: chybí povinná vlastní sklizeň.');continue;}if(want<wanted)decisions.push(b.name+': dávka omezena dostupnou vlastní sklizní.');const amounts={};amounts[b.primary]=(amounts[b.primary]||0)+want*b.share/100;amounts[b.secondary]=(amounts[b.secondary]||0)+want*(1-b.share/100);let missingCost=0;for(const [origin,n] of Object.entries(amounts))missingCost+=Math.max(0,n-greenAmount(origin))*(state.version>=3?getBeanCost(origin):ORIGINS[origin].cost)*1.18;const cost=missingCost+want*(typeof roastProcessingCost5==='function'?roastProcessingCost5(r,b):55);const hold=typeof productionHold5==='function'?productionHold5(r,cost,missingCost,plannedSpend,b,want):state.cash-cost<weeklyFixed()*1.2?'chybí hotovostní rezerva':null;if(hold){decisions.push('Pražení '+b.name+' pozastaveno: '+hold+'.');continue}for(const [origin,n] of Object.entries(amounts)){const missing=Math.max(0,n-greenAmount(origin));if(missing){const unit=(state.version>=3?getBeanCost(origin):ORIGINS[origin].cost)*1.18;state.cash-=missing*unit;cashSpend+=missing*unit;inventoryBought+=missing*unit;state.green.push({origin,kg:missing,cost:unit,quality:ORIGINS[origin].quality});if(typeof recordSupplyExpress5==='function')recordSupplyExpress5(origin,missing,missing*unit);decisions.push('Expresní nákup '+round(missing)+' kg '+origin+' (+18 %).')}}const result=roastBatch(r,b,want,true);used+=want*effort;greenUsed+=want;output+=result.kg;plannedSpend+=cost;cashSpend+=result.processing;processing+=result.processing;decisions.push(b.name+': '+round(result.kg)+' kg pro síť a kontrakty.');}}
r.last={used:round(used),greenInput5:greenUsed,capacity:cap,output:round(output),operatingCost:r.upkeep+r.staff*r.wage+(r.manager?.salary||0),decisions,utilization:cap?used/cap:0};r.manualUsed=0;if(typeof recordCraftManual5==='function'){r.manualOutput5=0;r.manualInput5=0;}r.condition=clamp(r.condition-.5,20,100);}return {cashSpend,inventoryBought,processing};}
function simulateEstates(){let expenses=0;for(const e of state.estates){e.cycle++;const risk=(state.week+ESTATES.findIndex(o=>o.id===e.sourceId)*3)%13===0?'sucho':(state.week+e.hectares)%17===0?'choroba':null;const staffing=clamp(e.staff/(4+e.yieldUpgrade),.35,1.2),method=e.method==='quality'?.85:e.method==='volume'?1.18:1,healthChange=(staffing-1)*5+(e.manager?(e.manager.skill-65)*.025:0)+(e.irrigation?1:0)-(risk==='sucho'?(e.irrigation?2:10):risk==='choroba'?8:0);e.health=clamp(e.health+healthChange,25,99);const wages=e.staff*e.wage,cost=e.upkeep+wages+(e.manager?.salary||0)+(e.method==='quality'?3500:0)+(typeof estateGrowingCost5==='function'?estateGrowingCost5(e):0);expenses+=cost;e.wipCost=(e.wipCost||0)+cost;e.last={expense:cost,risk,harvest:0,quality:0,decisions:[]};if(e.manager&&e.health<65&&state.cash>weeklyFixed()*3&&e.staff<6){e.staff++;e.last.decisions.push('Přijat další pracovník kvůli zdraví porostu.')}if(e.cycle>=e.period){const kg=round(e.yield*(1+e.yieldUpgrade*.25)*staffing*method*(e.health/100)*((risk==='sucho'&&!e.irrigation)?.8:1)*(typeof estateYield5==='function'?estateYield5(e):1)),quality=clamp(e.quality+(e.method==='quality'?3:e.method==='volume'?-5:0)+(e.manager?(e.manager.skill-65)*.05:0)+(typeof estateQuality5==='function'?estateQuality5(e):0),30,99),shipping=kg*(26+(typeof estateProcessingCost5==='function'?estateProcessingCost5(e):0));expenses+=shipping;const unit=(e.wipCost+shipping)/Math.max(1,kg);e.wipCost=0;state.shipments.push({id:uid('shipment'),origin:e.origin,kg,cost:unit,quality,due:state.week+2+(typeof estateProcessingWeeks5==='function'?estateProcessingWeeks5(e):0),source:e.name});if(typeof stampHarvest5==='function')stampHarvest5(e,state.shipments.at(-1));e.last.harvest=kg;e.last.quality=round(quality);e.cycle=0;log('Sklizeň: '+e.name,kg+' kg zrn, kvalita '+round(quality)+'. Zpracování a přeprava '+(2+(typeof estateProcessingWeeks5==='function'?estateProcessingWeeks5(e):0))+' týdnů, náklad '+money(shipping)+'.')}}return expenses;}
function simulateProjects(){let costs=0;const it=state.departments.it;for(const [key,p] of Object.entries(state.projects)){if(!it||!p.budget||p.done)continue;costs+=p.budget;p.progress=clamp(p.progress+it*5+p.budget/2000,0,100);if(p.progress>=100){p.done=true;p.budget=0;log(key==='loyalty'?'Spuštěna věrnostní aplikace':'Spuštěn e-shop',key==='loyalty'?'Hosté se častěji vracejí. Aplikace vyžaduje aktivní IT tým.':'Prodáváš balenou kávu z dostupných zásob. Provoz vyžaduje aktivní IT tým.')}}return costs;}
